18	#[derive(Clone)]
19	pub struct AuthMiddleware<S> {
20	    auth_keys: Arc<AuthKeys>,
21	    service: S,
22	}
23	
24	async fn check(auth_keys: Arc<AuthKeys>, mut req: Request) -> Result<Request, Status> {
25	    // When the audit logger trusts forwarded headers, prefer the raw
26	    // `X-Forwarded-For` value so audit entries record the real client address
27	    // rather than the proxy address.  Fall back to the TCP peer address.
28	    let remote = if audit_trust_forwarded_headers() {
29	        forwarded::forwarded_for(&req)
30	    } else {
31	        None
32	    }
33	    .or_else(|| {
34	        req.extensions()
35	            .get::<tonic::transport::server::TcpConnectInfo>()
36	            .and_then(|info| info.remote_addr())
37	            .map(|addr| addr.ip().to_string())
38	    });
39	
40	    let tracing_id = extract_tracing_id(|h| {
41	        req.headers()
42	            .get(h)
43	            .and_then(|val| val.to_str().ok())
44	            .map(str::to_string)
45	    });
46	
47	    // Allow health check endpoints to bypass authentication
48	    let path = req.uri().path();
49	    if path == "/qdrant.Qdrant/HealthCheck" || path == "/grpc.health.v1.Health/Check" {
50	        // Set default full access for health check endpoints
51	        let auth = Auth::new(
52	            Access::full("Health check endpoints have full access without authentication"),
53	            None,
54	            remote,
55	            AuthType::None,
56	            tracing_id,
57	        );
58	        let inference_token = InferenceToken(None);
59	
60	        req.extensions_mut().insert(auth);
61	        req.extensions_mut().insert(inference_token);
62	
63	        return Ok(req);
64	    }
65	
66	    let (access, inference_token, auth_type, subject) = auth_keys
67	        .validate_request(|key| req.headers().get(key).and_then(|val| val.to_str().ok()))
68	        .await
69	        .map_err(|e| {
70	            log_denied_auth(path, remote.clone(), tracing_id.clone(), &e);
71	            match e {
72	                AuthError::Unauthorized(e) => Status::unauthenticated(e),
73	                AuthError::Forbidden(e) => Status::permission_denied(e),
74	                AuthError::StorageError(e) => Status::from(e),
75	            }
76	        })?;
77	
78	    let auth = Auth::new(access, subject, remote, auth_type, tracing_id);
79	
80	    let previous = req.extensions_mut().insert(auth);
81	
82	    debug_assert!(
83	        previous.is_none(),
84	        "Previous auth object should not exist in the request"
85	    );
86	
87	    let previous_token = req.extensions_mut().insert(inference_token);
88	
89	    debug_assert!(
90	        previous_token.is_none(),
91	        "Previous inference token should not exist in the request"
92	    );
93	
94	    Ok(req)
95	}
