97	impl<S> Service<Request> for AuthMiddleware<S>
98	where
99	    S: Service<Request, Response = Response> + Clone + Send + 'static,
100	    S::Future: Send + 'static,
101	{
102	    type Response = S::Response;
103	    type Error = S::Error;
104	    type Future = BoxFuture<'static, Result<Self::Response, S::Error>>;
105	
106	    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
107	        self.service.poll_ready(cx)
108	    }
109	
110	    fn call(&mut self, request: Request) -> Self::Future {
111	        let auth_keys = self.auth_keys.clone();
112	        let mut service = self.service.clone();
113	
114	        Box::pin(async move {
115	            match check(auth_keys, request).await {
116	                Ok(req) => service.call(req).await,
117	                Err(e) => Ok(e.to_http()),
118	            }
119	        })
120	    }
121	}
