147	/// Extract the per-request [`Auth`] context from a tonic request.
148	///
149	/// When no authentication middleware is configured, a default `Auth` with full
150	/// access is returned.
151	pub fn extract_auth<R>(req: &mut tonic::Request<R>) -> Auth {
152	    req.extensions_mut().remove::<Auth>().unwrap_or_else(|| {
153	        Auth::new(
154	            Access::full("All requests have full by default access when API key is not configured"),
155	            None,
156	            None,
157	            AuthType::None,
158	            extract_tracing_id(|h| {
159	                req.metadata()
160	                    .get(h)
161	                    .and_then(|val| val.to_str().ok())
162	                    .map(str::to_string)
163	            }),
164	        )
165	    })
166	}
