// ---------------------------------------------------------------------------
// File abstraction
// ---------------------------------------------------------------------------

/// Abstraction over a readable, byte-addressable file used by
/// [`StorageReadService`].
///
/// This is generic so that alternative backends can be plugged in, while the
/// concrete type used in production (and in tests) is [`MmapFile`].
pub trait StorageFile: Send + Sync + Sized + 'static {
    /// Open the file at `path` for reading.
    fn open(path: &Path) -> std::io::Result<Self>;

    /// Total length of the file, in bytes.
    fn len(&self) -> u64;

    /// Whether the file is empty.
    fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// The full contents of the file as a byte slice.
    fn as_bytes(&self) -> &[u8];
}

/// A memory-mapped, read-only view of a file on disk.
///
/// Empty files are represented without an underlying mapping because mapping a
/// zero-length file is not supported by the OS.
pub struct MmapFile {
    mmap: Option<memmap2::Mmap>,
    length: u64,
}

impl StorageFile for MmapFile {
    fn open(path: &Path) -> std::io::Result<Self> {
        let length = fs::metadata(path)?.len();
        let mmap = if length == 0 {
            None
        } else {
            Some(open_read_mmap(path, AdviceSetting::Global, false)?)
        };
        Ok(MmapFile { mmap, length })
    }

    fn len(&self) -> u64 {
        self.length
    }

    fn as_bytes(&self) -> &[u8] {
        match &self.mmap {
            Some(mmap) => &mmap[..],
            None => &[],
        }
    }
}

